import {
  campaignConversionReportInputSchema,
  campaignConversionReportSchema,
} from "@/services/conversion/reporting/campaignConversionReportSchema";
import { getCampaignConversionReport } from "@/services/conversion/reporting/getCampaignConversionReport";
import {
  campaignConversionOptimizationSchema,
  serializeCampaignConversionOptimization,
} from "@/services/metaAds/campaignConversionOptimizationSchema";
import { getCampaignConversionOptimization } from "@/services/metaAds/getCampaignConversionOptimization";
import { assertCanViewCampaign } from "@/services/permission/assertCanViewCampaign";
import { canManagePlatform } from "@/services/permission/canManagePlatform";
import { getCampaignGrossMultiplier } from "@/services/report/helpers/getCampaignGrossMultiplier";
import { authProcedure } from "@/trpc/procedures/authed";

export const getCampaignConversionsQuery = authProcedure
  .input(campaignConversionReportInputSchema)
  // The ladder rides along rather than living in the report loader: the funnel the page already
  // shows is what the optimizer climbs, but the loader is platform-neutral and must stay free of
  // `meta_*` reads, so the two services are composed here instead.
  .output(campaignConversionReportSchema.extend({ optimization: campaignConversionOptimizationSchema.optional() }))
  .query(async ({ ctx, input }) => {
    // Readable by anyone who may view the campaign, which `assertCanViewCampaign` scopes to its
    // advertiser and agency. Customer data needs no platform-admin gate because the report cannot
    // reach another advertiser: the input names one campaign, and the query pins every branch to that
    // campaign's owning advertiser (`credential.brand_id = …`). Identity labels are the
    // advertiser's own customer ids or truncated hash prefixes, never a raw email or phone.
    // Funnel and purchase settings are fixed at campaign creation.
    await assertCanViewCampaign({
      db: ctx.readOnlyDb,
      permissions: ctx.session.user.permissions,
      campaignId: input.campaignId,
    });
    // Paid spend and the Meta ad ids follow the Boost tab's rules (getCampaignMetaAdsQuery): anyone
    // but a platform admin gets spend scaled by the campaign's gross multiplier (fee-inclusive only
    // when the fee is undisclosed), so the two surfaces cannot be divided into the platform fee; ad
    // ids name objects in the platform's own ad account.
    const isPlatformAdmin = canManagePlatform({ permissions: ctx.session.user.permissions });
    const spendMultiplier = isPlatformAdmin
      ? 1
      : await getCampaignGrossMultiplier({ db: ctx.readOnlyDb, campaignId: input.campaignId });
    const [report, optimization] = await Promise.all([
      getCampaignConversionReport({ db: ctx.readOnlyDb, input, spendMultiplier }),
      getCampaignConversionOptimization({ db: ctx.readOnlyDb, campaignId: input.campaignId }),
    ]);
    return {
      ...report,
      adBreakdown: {
        ...report.adBreakdown,
        rows: report.adBreakdown.rows.map((row) => ({ ...row, remoteAdId: isPlatformAdmin ? row.remoteAdId : null })),
      },
      ...(optimization === undefined ? {} : { optimization: serializeCampaignConversionOptimization(optimization) }),
    };
  });
import type { AppsAdPlatform } from "evangelist-exchange-db";
import { sql } from "kysely";

import { isConversionTestData, whereConversionReportable } from "@/services/conversion/conversionTestData";
import { buildBestAvailableConversionIdentityQuery } from "@/services/conversion/reporting/buildBestAvailableConversionIdentityQuery";
import type { CampaignConversionReportInput } from "@/services/conversion/reporting/campaignConversionReportSchema";

/**
 * Aggregate before pagination in PostgreSQL. The bounded customer timeline is the only event list
 * returned to the application; campaign-wide counts never depend on a sample or a row limit.
 * Explicit CTEs keep the ordered funnel and click/customer counting units separate.
 */
export function buildCampaignConversionReportQuery({
  input,
  advertiserStages,
  purchaseEventNames,
  paidAdPlatformId,
  referralCodesEnabled,
}: {
  input: CampaignConversionReportInput & { targetEvent: string };
  advertiserStages: Array<{ eventName: string; label: string }>;
  purchaseEventNames: string[];
  /** The campaign's paid boost platform; null for a campaign without a boost. */
  paidAdPlatformId: AppsAdPlatform | null;
  /** Off leaves every referral code out of the report, as if the registry were empty. */
  referralCodesEnabled: boolean;
}) {
  // Redirects belong to Evangelist and are always the entry to the tracked journey.
  // Only advertiser stages belong to the saved campaign configuration.
  const stages = [{ label: "Redirect", eventName: "page_redirect" }, ...advertiserStages];
  // Identity is resolved inside each branch of the cohort below rather than over their union, so
  // the events relation is materialized once. Click identity is this campaign's own visit, which
  // a branch supplies: an event that arrived through a referral code has none, and the foreign
  // click it may still name would invent a customer with no redirect.
  const identityExpressions = (campaignClickId: ReturnType<typeof sql>) => {
    // The hashed external id is a kind of its own, never compared with the raw one: an advertiser
    // may salt it, so equal spellings across the two columns say nothing about one customer.
    const value =
      input.identity === "externalCustomerId"
        ? sql`event.external_customer_id`
        : input.identity === "externalIdHash"
          ? sql`event.external_id_sha256`
          : input.identity === "emailHash"
            ? sql`event.email_sha256`
            : input.identity === "phoneHash"
              ? sql`event.phone_sha256`
              : campaignClickId;
    return {
      key: input.identity === "clickId" ? campaignClickId : sql`event.client_event_namespace || ':' || ${value}`,
      label:
        input.identity === "externalIdHash"
          ? sql`'External ID ' || left(${value}, 12)`
          : input.identity === "emailHash"
            ? sql`'Email ' || left(${value}, 12)`
            : input.identity === "phoneHash"
              ? sql`'Phone ' || left(${value}, 12)`
              : value,
    };
  };
  // Both branches of the events union carry the same columns.
  const bestAvailableIdentifiers = sql`event.external_customer_id, event.external_id_sha256, event.email_sha256,
    event.phone_sha256,`;
  const clickIdentity = identityExpressions(sql`clicks.id`);
  const codeIdentity = identityExpressions(sql`null::text`);
  const stageRows = sql.join(
    stages.map((stage, index) => sql`(${index}::integer, ${stage.eventName}::text, ${stage.label}::text)`),
  );
  // One prefix-maximum pass per stage over each identity's timeline (its redirects and stage events
  // in time order). At a row, reached_k is the latest redirect from which the identity has chained
  // through stages 1..k at or before that row; a stage-k row qualifies when reached_(k-1) lies within
  // the chaining interval before it, and then carries that redirect forward as its own anchor.
  // Because a later redirect can only widen the window, keeping the maximum anchor is exactly
  // evaluating every redirect's journey separately and taking the best outcome, without the
  // redirects × events product that made one shared identity (a placeholder customer id, one heavy
  // returning customer) quadratic in the customer modes.
  const timelineWindow = sql`partition by customer_key order by occurred_at, stage_index
    rows between unbounded preceding and current row`;
  let chainPasses = sql`select customer_key, occurred_at, stage_index,
      max(occurred_at) filter (where stage_index = 0) over (${timelineWindow}) as reached_0
    from timeline`;
  advertiserStages.forEach((_stage, offset) => {
    const index = offset + 1;
    const previous = sql.id(`reached_${index - 1}`);
    chainPasses = sql`select *, max(${previous}) filter (where stage_index = ${index}
        and ${previous} >= occurred_at - interval '30 days')
        over (${timelineWindow}) as ${sql.id(`reached_${index}`)}
      from (${chainPasses}) ${sql.id(`pass_${index}`)}`;
  });
  // A stage-k row with a non-null reached_k means some stage-k row at or before it qualified, so
  // reading the flag on the stage's own rows finds every identity that reached the stage.
  const reachedStages = sql.join(
    stages.map(
      (stage, index) => sql`select distinct customer_key, ${index}::integer as stage_index,
        ${stage.eventName}::text as event_name from journey_chain
        where stage_index = ${index} and ${sql.id(`reached_${index}`)} is not null`,
    ),
    sql` union all `,
  );
  const stageFilter = input.stageFilter
    ? sql`customer.customer_key in (select reached.customer_key from reached_stages reached
        where reached.event_name = ${input.stageFilter})`
    : sql`true`;
  const searchFilter = input.search ? sql`position(lower(${input.search}) in lower(customer.label)) > 0` : sql`true`;
  // Ad selection filters customer rows only. Campaign totals and their spend denominator
  // stay campaign-wide, and a selected customer's complete journey remains visible.
  const customerAdFilter = input.customerAdId
    ? sql`customer.customer_key in (select event.customer_key from normalized event
        where event.ad_id = ${input.customerAdId})`
    : sql`true`;
  // The same for a referral code: journeys with an event credited to it or a visit through its
  // creator's clips.
  const customerReferralCodeFilter = input.customerReferralCodeId
    ? sql`customer.customer_key in (select event.customer_key from normalized event
        where event.referral_code_id = ${input.customerReferralCodeId})`
    : sql`true`;
  // A breakdown row's customer count is the stage-qualified cohort shown when the row is selected.
  const stageQualifiedCustomer = input.stageFilter
    ? sql`customer_key in (select customer_key from stage_customers)`
    : sql`true`;
  // PostgreSQL numeric sums can exceed the finite JavaScript range even when each accepted
  // input was finite. Keep such amounts out of JSON numbers, and report their absence explicitly.
  const maximumAmount = sql`${String(Number.MAX_VALUE)}::numeric`;
  // One exact, case-sensitive membership rule for every purchase count and monetary aggregate.
  // This list never changes raw target matching or the ordered funnel above.
  const isPurchase = (eventNameColumn: string) =>
    sql`${sql.ref(eventNameColumn)} collate "C" = any(${purchaseEventNames}::text[])`;

  return sql<{ report: unknown }>`
    with ${input.identity === "bestAvailable" ? sql`recursive` : sql``} links as materialized (
      -- A link generated for an ad of the campaign's boost platform is the paid source of every
      -- visit through it, and its ad key is the one the ad breakdown's rows carry. Paid CPA and
      -- ROAS divide that platform's spend, so a link generated for another platform's ad must not
      -- count against it.
      select binding.link_id, binding.ad_id,
        ${paidAdPlatformId === null ? sql`false` : sql`binding.ad_platform_id = ${paidAdPlatformId}`} as is_paid,
        ${isConversionTestData("link.origin")} as is_test_data,
        -- The clip's creator, whose personal code the redirect adds to the landing URL.
        post.user_id as creator_user_id
      from apps.campaign_conversion_link binding
      join apps.post post on post.channel_platform_unique_post_id = binding.post_id
        and post.channel_platform_id = binding.channel_platform_id
      join apps.campaign campaign on campaign.id = post.campaign_id
      join apps.conversion_link link on link.id = binding.link_id
      where post.campaign_id = ${input.campaignId}
        -- A post move cannot transfer visitor history across advertisers; unresolved ownership grants no membership.
        and link.brand_id = campaign.brand_id
        and ${whereConversionReportable("link.origin")}
    ), clicks as materialized (
      select click.id, click.clicked_at, links.ad_id, links.is_paid, links.creator_user_id
      from links join apps.conversion_click click on click.link_id = links.link_id
      where click.ignore = false
    ), codes as materialized (
      -- The campaign's referral registry. A code is the second way an event reaches this report,
      -- and the only way one with no visit at all can: nothing here joins a submitted spelling,
      -- so renaming a code never moves the conversions already credited to its row. With referral
      -- codes switched off for the campaign the registry reads as empty, so no code-only event, no
      -- code on a visit and no registry row reaches any figure below.
      select code.id, code.code, code.channel_platform_id as platform,
        code.channel_platform_unique_account_handle as handle, code.disabled_at,
        code.user_id, creator.display_name as creator_display_name,
        ${isConversionTestData("code.origin")} as is_test_data
      from apps.conversion_referral_code code
      left join apps."user" creator on creator.id = code.user_id
      where code.campaign_id = ${input.campaignId}
        and ${referralCodesEnabled ? sql`true` : sql`false`}
        and ${whereConversionReportable("code.origin")}
    ), events as materialized (
      -- The two ways an event belongs to this campaign, each driven from its own index, and one
      -- row per event: the visit path first, then the codes whose event has no visit here. An
      -- event on both keeps the first branch, so the paid facts stay the click's — a code carries
      -- no visit, no ad and no paid source of its own.
      select event.id, event.event_name, event.occurred_at, clicks.id as click_id,
        event.value, trim(event.currency_code) as currency, clicks.is_paid, clicks.ad_id,
        event.attributed_referral_code_id as referral_code_id, event.client_event_namespace,
        case when code.id is not null then 'both' else 'clickOnly' end as attribution,
        ${isConversionTestData("credential.origin")} as is_test_data,
        ${input.identity === "bestAvailable" ? bestAvailableIdentifiers : sql``}
        ${clickIdentity.key} as own_key, ${clickIdentity.label} as own_label
      from clicks join apps.conversion_event event on event.attributed_click_id = clicks.id
      join global.api_credential credential on credential.id = event.api_credential_id
      left join codes code on code.id = event.attributed_referral_code_id
      where event.ignore = false
        -- Historical attribution is immutable; a foreign credential's old event cannot supply
        -- this advertiser's revenue or customer identity.
        -- Resolve the single campaign owner in this statement's snapshot. Joining this equality
        -- through every click makes the planner underestimate events and repeatedly scan them.
        and credential.brand_id = (select brand_id from apps.campaign where id = ${input.campaignId})
        -- This reserved reporting stage is derived from our redirect record, never partner input.
        and event.event_name <> 'page_redirect'
        and ${whereConversionReportable("credential.origin")}
      union all
      select event.id, event.event_name, event.occurred_at, null::text,
        event.value, trim(event.currency_code) as currency, false, null::text,
        code.id, event.client_event_namespace,
        'codeOnly', ${isConversionTestData("credential.origin")},
        ${input.identity === "bestAvailable" ? bestAvailableIdentifiers : sql``}
        ${codeIdentity.key}, ${codeIdentity.label}
      from codes code join apps.conversion_event event on event.attributed_referral_code_id = code.id
      join global.api_credential credential on credential.id = event.api_credential_id
      where event.ignore = false

