        and ${referralCodesEnabled ? sql`true` : sql`false`}
        and ${whereConversionReportable("code.origin")}
    ), events as materialized (
      -- The two ways an event belongs to this campaign, each driven from its own index, and one
      -- row per event: the visit path first, then the codes whose event has no visit here. An
      -- event on both keeps the first branch, so the paid facts stay the click's — a code carries
      -- no visit, no ad and no paid source of its own.
      select event.id, event.event_name, event.occurred_at, clicks.id as click_id,
        event.value, trim(event.currency_code) as currency, clicks.is_paid, clicks.ad_id,
        event.attributed_referral_code_id as referral_code_id, event.client_event_namespace,
        case when code.id is not null then 'both' else 'clickOnly' end as attribution,
        ${isConversionTestData("credential.origin")} as is_test_data,
        ${input.identity === "bestAvailable" ? bestAvailableIdentifiers : sql``}
        ${clickIdentity.key} as own_key, ${clickIdentity.label} as own_label
      from clicks join apps.conversion_event event on event.attributed_click_id = clicks.id
      join global.api_credential credential on credential.id = event.api_credential_id
      left join codes code on code.id = event.attributed_referral_code_id
      where event.ignore = false
        -- Historical attribution is immutable; a foreign credential's old event cannot supply
        -- this advertiser's revenue or customer identity.
        -- Resolve the single campaign owner in this statement's snapshot. Joining this equality
        -- through every click makes the planner underestimate events and repeatedly scan them.
        and credential.brand_id = (select brand_id from apps.campaign where id = ${input.campaignId})
        -- This reserved reporting stage is derived from our redirect record, never partner input.
        and event.event_name <> 'page_redirect'
        and ${whereConversionReportable("credential.origin")}
      union all
      select event.id, event.event_name, event.occurred_at, null::text,
        event.value, trim(event.currency_code) as currency, false, null::text,
        code.id, event.client_event_namespace,
        'codeOnly', ${isConversionTestData("credential.origin")},
        ${input.identity === "bestAvailable" ? bestAvailableIdentifiers : sql``}
        ${codeIdentity.key}, ${codeIdentity.label}
      from codes code join apps.conversion_event event on event.attributed_referral_code_id = code.id
      join global.api_credential credential on credential.id = event.api_credential_id
      where event.ignore = false
